        uint256 id = getNextEventId();
        result = createResultHandle(EOps.BitAnd, lhsType, abi.encodePacked(lhs, rhs));
        emit EBitAnd(lhs, rhs, result, id);
        setDigest(abi.encodePacked(result, id));
    }

